'use strict'
// Stable public API for crates/turbovec-napi.
// index.js is auto-generated by napi-rs on every build — import from here instead.
const { types } = require('node:util')
const native = require('./index.js')

function toLeUint8View(wordsOrBytes) {
  if (types.isBigUint64Array(wordsOrBytes)) {
    return new Uint8Array(wordsOrBytes.buffer, wordsOrBytes.byteOffset, wordsOrBytes.byteLength)
  }
  if (types.isUint8Array(wordsOrBytes)) {
    return wordsOrBytes instanceof Buffer || wordsOrBytes.constructor === Uint8Array
      ? wordsOrBytes
      : new Uint8Array(wordsOrBytes.buffer, wordsOrBytes.byteOffset, wordsOrBytes.byteLength)
  }
  throw new TypeError('EXPECTED_UINT8ARRAY_OR_BIGUINT64ARRAY')
}

// hashSourceRefs: native returns Buffer of raw LE u64 bytes.
// Wrap as BigUint64Array for zero-copy typed access.
function hashSourceRefs(refs) {
  const buf = native.hashSourceRefs(refs)
  return new BigUint64Array(buf.buffer, buf.byteOffset, buf.length / 8)
}

function batchHammingSearchTopK(queryWords, corpusFlatWords, wordsPerVec, topK) {
  return native.batchHammingSearchTopK(
    toLeUint8View(queryWords),
    toLeUint8View(corpusFlatWords),
    wordsPerVec,
    topK
  )
}

module.exports = {
  hashSourceRefs,
  dedupeEdgesJson: native.dedupeEdgesJson,
  scoreSom20X20: native.scoreSom20X20,
  loadJsonlPackets: native.loadJsonlPackets,
  packQdrantPayloads: native.packQdrantPayloads,
  turbovecSmoke: native.turbovecSmoke,
  hintExactCosineTopk: native.hintExactCosineTopk,
  hintTurbovecTopk: native.hintTurbovecTopk,
  computeDhash64: native.computeDhash64,
  batchHammingSearchTopK,
}
